import * as shopifyCart from '@shopify/theme-cart';
import { Module } from '../module/module';
import { PushCartRenderer } from './push-cart-renderer';
import { buildProperties } from './utils'; // eslint-disable-next-line import/no-default-export

export default class _class extends Module {
  constructor(...args) {
    super(...args);
    this._loading = false;
    this.renderer = new PushCartRenderer(this);
  }

  setupListeners() {
    super.setupListeners();
    this.listeners.add(document, 'submit', this.onFormSubmit);
    this.listeners.add(this.itemsEl, 'click', this.onRemoveClick);
    this.listeners.add(this.itemsEl, 'change', this.onQuantityUpdate);
  }

  async onFormSubmit(e) {
    if (!e.target.matches(this.globalSelectors.form)) return;
    e.preventDefault();
    const formData = new FormData(e.target);
    const id = Number(formData.get('id'));
    const quantity = Number(formData.get('quantity'));
    const properties = buildProperties(formData);
    this.loading = true;
    window.drawers.activeDrawerKey = 'cart';
    await shopifyCart.addItem(id, {
      properties,
      quantity
    });
    await this.render(await shopifyCart.getState());
  }

  async onRemoveClick(e) {
    if (e.target.closest(this.selectors.remove) == null) return;
    const item = e.target.closest(this.selectors.item);
    item.classList.add(this.data.get('itemLoadingClass'));
    await this.render(await shopifyCart.updateItem(item.dataset.key, {
      quantity: 0
    }));
  }

  async onQuantityUpdate(e) {
    if (e.target.closest(this.selectors.quantity) == null) return;
    const item = e.target.closest(this.selectors.item);
    item.classList.add(this.data.get('itemLoadingClass'));
    await this.render(await shopifyCart.updateItem(item.dataset.key, {
      quantity: parseInt(e.target.value, 10)
    }));
    item.classList.remove(this.data.get('itemLoadingClass'));
  }

  async render(state) {
    /*
      this.renderCart(await shopifyCart.updateItem(item.dataset.key, { quantity: 0 }))
      this.renderCartItems()
       The below is slightly less efficient than doing the above. The problem with the above is that the items won't get updated until the push cart subtotal and whatnot is updated. This causes a noticeable delay between the 2. The below makes this appear to all happen at the same time so it's a nicer effect for the user
     */
    await this.renderCartItems();
    this.renderCart(state);
  }

  async renderCartItems() {
    return fetch("/?section_id=push-cart-items").then(res => res.text()).then(html => {
      this.itemsEl.innerHTML = html;
      this.loading = false;
    });
  }

  renderCart(state) {
    this.renderer.render(state);
  }

  get globalSelectors() {
    return {
      form: '[data-push-cart-form]',
      cartCount: '[data-push-cart-count]'
    };
  }

  get loading() {
    return this._loading;
  }

  set loading(val) {
    this._loading = val;
    this.element.classList.toggle(this.data.get('loadingClass'), val);
  }

}
_class.methods = ['onFormSubmit', 'onRemoveClick', 'onQuantityUpdate'];
_class.targets = ['close', 'count', 'body', 'items', 'subtotal', 'remove', 'quantity', 'item'];